mapper.select:
SELECT

FROM tool_invocation_stats s
WHERE s.tenant_id = #{tenantId}
AND s.stat_hour >= #{from}
AND s.stat_hour <= #{to}

    AND s.kind = #{kind}

SELECT
CAST(DATE_FORMAT(s.stat_hour, '%Y-%m-%d %H:00:00') AS DATETIME) AS timePoint
CAST(DATE_FORMAT(DATE_SUB(s.stat_hour, INTERVAL WEEKDAY(s.stat_hour) DAY), '%Y-%m-%d 00:00:00') AS DATETIME) AS timePoint
CAST(DATE_FORMAT(s.stat_hour, '%Y-%m-01 00:00:00') AS DATETIME) AS timePoint
CAST(DATE_FORMAT(s.stat_hour, '%Y-%m-%d 00:00:00') AS DATETIME) AS timePoint
, s.kind AS kind, s.subject_id AS dimensionId, s.tool_name AS dimensionName, COALESCE(SUM(s.calls), 0) AS calls, COALESCE(SUM(s.successes), 0) AS successes, COALESCE(SUM(s.errors), 0) AS errors, COALESCE(SUM(s.denials), 0) AS denials, COALESCE(SUM(s.interruptions), 0) AS interruptions, COALESCE(SUM(s.sum_duration_ms), 0) AS sumDurationMs FROM tool_invocation_stats s WHERE s.tenant_id = #{tenantId} AND s.stat_hour >= #{from} AND s.stat_hour <= #{to}
AND s.kind = #{kind}
AND s.subject_id = #{subjectId}
GROUP BY timePoint, s.kind, s.subject_id, s.tool_name ORDER BY timePoint, calls DESC
